-- Fixed 2026-09-20: "YEAR" was a bare try_to_number() -- unguarded, so any
-- future non-whole value would silently round instead of reading NULL.
-- Live-checked a 1M-row sample: 0 fractional YEAR values today -- clean, a
-- landmine not a live bug. A matching staging model exists
-- (stg_fed_cms_medicare_dialysis_facilities__providers) but leaves YEAR as
-- TEXT (no column in its sample parsed cleanly as one type for every filled
-- value), where this mart deliberately casts it to a number -- swapping to
-- ref() would silently change YEAR's type, so this stays on source() and
-- only the bare cast is wrapped, with stg_int (macros/staging_casts.sql):
-- a year is a whole number, never a decimal.

with source as (
    select * from {{ source('ripple_raw', 'FED_CMS_MEDICARE_DIALYSIS_FACILITIES') }}
)

select
    STATE as state,
    CCN as ccn,
    PROVIDER_NAME as provider_name,
    CITY as city,
    OWNERSHIP_TYPE as ownership_type,
    ESRD_NETWORK as esrd_network,
    NPI as npi,
    CHAIN as chain,
    MODALITY as modality,
    ALTERNATE_CCNS as alternate_ccns,
    MEASURE as measure,
    {{ ripple_num('MEASURE_SCORE') }} as measure_score,
    {{ stg_int('"YEAR"') }} as year_col,
    MEASURE_ID as measure_id
from source
